#!/usr/bin/env bash
#
# Self-update support for the `a` CLI. The install is a git clone, so checking
# for updates is a `git fetch` and updating is a fast-forward pull.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool

[[ -n "${A_UPDATE_LOADED:-}" ]] && return 0
A_UPDATE_LOADED=1

A_UPDATE_INTERVAL_MINUTES="${A_UPDATE_INTERVAL_MINUTES:-1440}"

a_git() { git -C "$A_ROOT" "$@"; }

a_is_git_install() {
  command -v git >/dev/null 2>&1 && [[ -d "$A_ROOT/.git" ]]
}

# Number of upstream commits the local checkout is missing, based on the last
# fetch. Prints nothing when there is no upstream to compare against.
a_commits_behind() {
  a_git rev-list --count 'HEAD..@{u}' 2>/dev/null
}

# check_for_updates
#
# Warns when a previous background fetch found new commits, then starts a new
# fetch if the last one is older than A_UPDATE_INTERVAL_MINUTES. The fetch is
# detached and silent so it never slows down or clutters the command being run;
# its result surfaces on the next invocation. Set A_NO_UPDATE_CHECK=1 to opt out.
check_for_updates() {
  [[ -n "${A_NO_UPDATE_CHECK:-}" ]] && return 0
  a_is_git_install || return 0

  local behind
  behind="$(a_commits_behind)"
  if [[ "${behind:-0}" -gt 0 ]]; then
    printf '%s!%s a: update available (%s new commit%s). Run %sa update%s\n' \
      "$RED" "$RESET" "$behind" "$([[ "$behind" -eq 1 ]] || printf s)" "$BOLD" "$RESET" >&2
  fi

  local stamp="$A_ROOT/.git/a-last-update-check"
  if [[ -f "$stamp" && -n "$(find "$stamp" -mmin "-$A_UPDATE_INTERVAL_MINUTES" 2>/dev/null)" ]]; then
    return 0
  fi
  touch "$stamp" 2>/dev/null || return 0
  ( a_git fetch --quiet >/dev/null 2>&1 & ) </dev/null >/dev/null 2>&1
}
